// Render returns the rendered bootstrap configuration as a JSON byte slice.
func (c *BootstrapConfig) Render() ([]byte, error) {
	// Resolve any environment variables in the config fields.
	if err := c.resolveEnvVars(); err != nil {
		return nil, err
	}

	// Parse the template.
	tmpl, err := template.New("bootstrap").Parse(c.Template())
	if err != nil {
		return nil, fmt.Errorf("failed to parse bootstrap template: %w", err)
	}

	// Execute the template with the config.
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, c); err != nil {
		return nil, fmt.Errorf("failed to render bootstrap config: %w", err)
	}

	// Ensure the JSON is valid and properly formatted.
	var raw interface{}
	if err := json.Unmarshal(buf.Bytes(), &raw); err != nil {
		return nil, fmt.Errorf("rendered bootstrap config is not valid JSON: %w", err)
	}

	// Marshal again with indentation for readability.
	return json.MarshalIndent(raw, "", "  ")
}

