	if err != nil {
		return "", fmt.Errorf("failed to parse bootstrap template: %w", err)
	}

	// Execute the template with the context.
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, ctx); err != nil {
		return "", fmt.Errorf("failed to render bootstrap config: %w", err)
	}

	// Return the rendered configuration.
	return buf.String(), nil
}

