	executor   executor.Executor
	memcached  *memcached.Memcached
	proc       *executor.Process
	metrics    chan *parse.Metric
	running    bool
	stop       chan struct{}
}

// New creates a new Mutilate workload.
func New(config *Config) *Mutilate {
	return &Mutilate{
		config:     config,
		executor:   executor.New(),
		proc:       nil,
		metrics:    make(chan *parse.Metric),
		running:    false,
		stop:       make(chan struct{}),
	}
}

// Start runs the mutilate workload.
func (m *Mutilate) Start() error {
	if m.running {
		return errors.New("mutilate workload is already running")
	}

	// Ensure memcached is running.
	memcached, err := memcached.New(&memcached.Config{
		Host:    m.config.MemcachedHost,
		Port:    m.config.MemcachedPort,
		Verbose: true,
	})

