func CopyStringMap(a map[string]string) map[string]string {
	if a == nil {
		return nil
	}

	out := make(map[string]string)
	for key, value := range a {
		out[key] = value
	}

	return out
}

// CopyStringMapInterface makes a deep copy of the passed in map[string]interface{}
