func isAuthorized(auth string) bool {
	// Extract the token from the Authorization header (e.g., "Bearer <token>")
	if !strings.HasPrefix(auth, "Bearer ") {
		return false
	}
	token := strings.TrimPrefix(auth, "Bearer ")

	// Compare with the expected token (in a real app, this would be more secure)
	expectedToken := os.Getenv("FLEXDEV_ADMIN_TOKEN")
	return token == expectedToken
}

